#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Mask3 {
    width: usize,
    height: usize,
    depth: usize,
    cells: Vec<bool>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MaskError {
    ShapeOverflow,
    LengthMismatch,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Overlap {
    pub both_set: usize,
    pub both_clear: usize,
    pub left_only: usize,
    pub right_only: usize,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Scores {
    pub dice: f64,
    pub jaccard: f64,
}

impl Mask3 {
    pub fn new(width: usize, height: usize, depth: usize, cells: Vec<bool>) -> Result<Self, MaskError> {
        let expected = width
            .checked_mul(height)
            .and_then(|n| n.checked_mul(depth))
            .ok_or(MaskError::ShapeOverflow)?;
        if cells.len() != expected {
            return Err(MaskError::LengthMismatch);
        }
        Ok(Self { width, height, depth, cells })
    }

    pub fn dimensions(&self) -> (usize, usize, usize) {
        (self.width, self.height, self.depth)
    }

    pub fn cells(&self) -> &[bool] {
        &self.cells
    }
}

impl Overlap {
    pub fn scores(&self) -> Scores {
        let union = self.both_set + self.left_only + self.right_only;
        if union == 0 {
            return Scores { dice: 0.0, jaccard: 0.0 };
        }
        let intersection = self.both_set as f64;
        Scores {
            dice: 2.0 * intersection / (2.0 * intersection + self.left_only as f64 + self.right_only as f64),
            jaccard: intersection / union as f64,
        }
    }
}

pub fn compare_masks(left: &Mask3, right: &Mask3) -> Result<Overlap, MaskError> {
    if left.dimensions() != right.dimensions() {
        return Err(MaskError::LengthMismatch);
    }
    let mut result = Overlap::default();
    for (&a, &b) in left.cells.iter().zip(&right.cells) {
        match (a, b) {
            (true, true) => result.both_set += 1,
            (false, false) => result.both_clear += 1,
            (true, false) => result.left_only += 1,
            (false, true) => result.right_only += 1,
        }
    }
    Ok(result)
}

