#[path = "solution.rs"]
mod solution;

use solution::{compare_masks, Mask3, MaskError};

#[test]
fn counts_all_four_corresponding_cell_states() {
    let left = Mask3::new(2, 2, 2, vec![true, true, false, false, true, false, true, false]).unwrap();
    let right = Mask3::new(2, 2, 2, vec![true, false, true, false, true, false, false, true]).unwrap();

    let overlap = compare_masks(&left, &right).unwrap();
    assert_eq!(overlap.both_set, 2);
    assert_eq!(overlap.both_clear, 2);
    assert_eq!(overlap.left_only, 2);
    assert_eq!(overlap.right_only, 2);

    let scores = overlap.scores();
    assert!((scores.dice - 0.5).abs() < f64::EPSILON);
    assert!((scores.jaccard - (1.0 / 3.0)).abs() < f64::EPSILON);
}

#[test]
fn empty_and_all_clear_masks_have_perfect_scores() {
    for mask in [
        Mask3::new(0, 7, 9, vec![]).unwrap(),
        Mask3::new(2, 1, 1, vec![false, false]).unwrap(),
    ] {
        let overlap = compare_masks(&mask, &mask).unwrap();
        let scores = overlap.scores();
        assert_eq!(scores.dice, 1.0);
        assert_eq!(scores.jaccard, 1.0);
    }
}

#[test]
fn constructor_rejects_wrong_length_and_overflow() {
    assert!(matches!(
        Mask3::new(2, 3, 1, vec![false; 5]),
        Err(MaskError::LengthMismatch)
    ));
    assert!(matches!(
        Mask3::new(usize::MAX, 2, 1, vec![]),
        Err(MaskError::ShapeOverflow)
    ));
}

#[test]
fn dimensions_must_match_even_when_cell_counts_match() {
    let left = Mask3::new(1, 2, 1, vec![true, false]).unwrap();
    let right = Mask3::new(2, 1, 1, vec![true, false]).unwrap();
    assert!(matches!(
        compare_masks(&left, &right),
        Err(MaskError::LengthMismatch)
    ));
}

#[test]
fn comparison_is_repeatable_and_does_not_mutate_masks() {
    let left = Mask3::new(3, 1, 1, vec![true, false, true]).unwrap();
    let right = Mask3::new(3, 1, 1, vec![false, false, true]).unwrap();

    for _ in 0..2 {
        let overlap = compare_masks(&left, &right).unwrap();
        assert_eq!((overlap.both_set, overlap.both_clear), (1, 1));
        assert_eq!((overlap.left_only, overlap.right_only), (1, 0));
    }
}

